def sigmoid(x): return 1/(1+np.exp(-x))

def lstm_forget_gate(h_prev, x_t, W_f, b_f):
    # Forget gate decides what to discard from long-term memory
    return sigmoid(np.dot(W_f, np.concatenate([h_prev, x_t])) + b_f)

